// Confere o pedido do funil: marca, oferta, link de compra (WhatsApp ou checkout), tipo de quiz, perguntas, captura e prova social.
let b = $('🔔 Pedido do quiz (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const crypto = require('crypto');
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>{}\\]/g, ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const texto = (v, max) => String(v ?? '').replace(/\r/g, '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>{}\\]/g, ' ').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, max);
const TIPOS = { recomendacao: 'recomendação (qual opção/produto é o ideal para a pessoa)', diagnostico: 'diagnóstico (descobre o nível, a situação ou o problema da pessoa)', perfil: 'perfil (descubra seu estilo/perfil)' };
const TONS = { descontraido: 'descontraído', profissional: 'profissional', acolhedor: 'acolhedor', divertido: 'divertido' };
const dados = {
  marca: limpa(b.marca, 60), produto: limpa(b.produto, 120), descricao: texto(b.descricao, 1500), publico: limpa(b.publico, 200),
  preco: limpa(b.preco, 40), condicao: limpa(b.condicao, 160), garantia: limpa(b.garantia, 160), prova: texto(b.prova, 1200),
  tipo: TIPOS[b.tipo] ? b.tipo : 'recomendacao', tom: TONS[b.tom] ? b.tom : 'descontraido',
};
let whatsapp = String(b.whatsapp || '').replace(/\D/g, '');
if (whatsapp.length === 10 || whatsapp.length === 11) whatsapp = '55' + whatsapp;
const checkout = /^https:\/\/[^\s<>"']{4,300}$/.test(String(b.checkout || '').trim()) ? String(b.checkout).trim() : '';
const op = {
  perguntas: Math.min(10, Math.max(4, parseInt(b.perguntas, 10) || 7)), cor: /^#[0-9a-fA-F]{6}$/.test(b.cor || '') ? String(b.cor).toUpperCase() : '',
  imagens: b.imagens !== false, pedir_whatsapp: b.pedir_whatsapp !== false, pedir_email: b.pedir_email === true, crm: b.crm !== false,
  destino: checkout ? 'checkout' : 'whatsapp', whatsapp: whatsapp.length >= 12 && whatsapp.length <= 13 ? whatsapp : '', checkout,
};
const erros = [];
if (dados.marca.length < 2) erros.push('Diga o nome do seu negócio.');
if (dados.produto.length < 3) erros.push('Diga o que você está oferecendo (o produto ou serviço).');
if (dados.descricao.length < 20) erros.push('Conte um pouco do produto e para quem ele é (pelo menos uma frase).');
if (!op.whatsapp && !op.checkout) erros.push('Informe o WhatsApp (com DDD) ou o link de compra (https://...) para onde o resultado leva.');
const slug = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
let curto = '';
for (const p of slug(dados.marca + ' ' + dados.produto).split('-').slice(0, 5)) { if ((curto + '-' + p).length > 30) break; curto = curto ? curto + '-' + p : p; }
const id = (curto || 'quiz') + '-' + crypto.randomBytes(2).toString('hex');
const chave = crypto.randomBytes(16).toString('hex');
const base = String($('🔔 Pedido do quiz (POST)').first().json.webhookUrl || '').split('/webhook/')[0];
const resumo_ia = `NEGÓCIO: ${dados.marca}
OFERTA (o que o quiz vai recomendar no final): ${dados.produto}
DETALHES DO PRODUTO E PARA QUEM É:
${dados.descricao}
PÚBLICO: ${dados.publico || '(o dono não disse)'}
PREÇO: ${dados.preco || '(não informado: não fale de preço)'}
CONDIÇÃO/OFERTA ESPECIAL: ${dados.condicao || '(nenhuma: não invente desconto, brinde ou prazo)'}
GARANTIA: ${dados.garantia || '(nenhuma: não prometa garantia)'}
PROVA SOCIAL DO DONO (a única que pode aparecer): ${dados.prova || '(nenhuma: não invente depoimento, número de clientes ou avaliação)'}
TIPO DE QUIZ: ${TIPOS[dados.tipo]}
TOM: ${TONS[dados.tom]}
QUANTIDADE DE PERGUNTAS: ${op.perguntas}
FINAL DO FUNIL: ${op.destino === 'checkout' ? 'botão para a página de compra' : 'botão para conversar no WhatsApp'}`;
return [{ json: {
  valido: erros.length === 0, erros, id, chave, dados, op, resumo_ia, criado_em: Date.now(), base,
  link: `${base}/webhook/quiz/${id}/responder`, painel: `${base}/webhook/quiz-painel?id=${id}&chave=${chave}`, arquivos: `${base}/videos/arquivo`,
  chave_limite: '<SEGREDO_REMOVIDO>' + new Date().toISOString().slice(0, 13),
} }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Confere a estratégia: 2 a 4 perfis de resultado, a quantidade de perguntas pedida, 2 a 5 opções por pergunta,
// cada opção somando pontos para um perfil que existe e todo perfil alcançável. Prepara o pedido da copywriter.
const V = $('🧩 Confere o pedido').first().json;
let e = null;
try { e = parseJSON($('🤖 Estrategista do quiz').first().json.output); } catch (x) {}
e = e || {};
const T = (v, max) => {   // corta no fim de frase ou de palavra, nunca no meio
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max), fim = Math.max(c.lastIndexOf('. '), c.lastIndexOf('! '), c.lastIndexOf('? '));
  if (fim >= max * 0.55) return c.slice(0, fim + 1);
  const esp = c.lastIndexOf(' ');
  return (esp >= max * 0.55 ? c.slice(0, esp) : c.slice(0, max - 1)).replace(/[\s,;:.–—-]+$/, '') + '…';
};
// emojis novos demais (bloco U+1FA70–1FAFF, ex.: 🫖) não aparecem no Windows 10: troca por um que aparece em todo lugar
const emoji = (v, k) => { const m = String(v || '').match(/\p{Extended_Pictographic}(️|‍\p{Extended_Pictographic})*/u); return m && !/[\u{1FA70}-\u{1FAFF}]/u.test(m[0]) ? m[0] : ['✨', '🎯', '💡', '🌟', '✅'][k % 5]; };
const LETRAS = ['A', 'B', 'C', 'D'];
let perfis = (Array.isArray(e.perfis) ? e.perfis : []).filter(p => p && T(p.nome, 60)).slice(0, 4)
  .map((p, i) => ({ k: LETRAS[i], orig: String(p.k ?? ''), nome: T(p.nome, 50), emoji: emoji(p.emoji, i), quem_e: T(p.quem_e, 220), recomendacao: T(p.recomendacao, 260) }));
const ok = perfis.length >= 2;
if (!ok) perfis = [{ k: 'A', nome: 'Perfil Prático', emoji: '🎯', quem_e: '', recomendacao: '' }, { k: 'B', nome: 'Perfil Explorador', emoji: '🌟', quem_e: '', recomendacao: '' }];
const qualPerfil = (v, j) => { const s = String(v ?? '').trim(); const p = perfis.find(x => x.orig === s || x.k === s.toUpperCase() || x.nome.toLowerCase() === s.toLowerCase()); return p ? p.k : perfis[j % perfis.length].k; };
let perguntas = (Array.isArray(e.perguntas) ? e.perguntas : []).filter(q => q && T(q.texto, 140) && Array.isArray(q.opcoes) && q.opcoes.length >= 2).slice(0, Math.min(10, V.op.perguntas + 1))
  .map((q, i) => ({ k: 'p' + (i + 1), texto: T(q.texto, 140), ajuda: T(q.ajuda, 120), multipla: q.multipla === true,
    opcoes: q.opcoes.slice(0, 5).map((o, j) => ({ k: 'abcde'[j], texto: T(o && (o.texto || o), 80), emoji: emoji(o && o.emoji, j + i), perfil: qualPerfil(o && o.perfil, j), peso: Math.min(3, Math.max(1, parseInt(o && o.peso, 10) || 1)) }))
      .filter(o => o.texto) })).filter(q => q.opcoes.length >= 2);
perguntas.forEach((q, i) => { q.k = 'p' + (i + 1); });
// todo perfil precisa poder ganhar: se algum não aparece em nenhuma opção, a última opção da pergunta com mais opções passa a ser dele
for (const p of perfis) {
  if (perguntas.some(q => q.opcoes.some(o => o.perfil === p.k))) continue;
  const q = perguntas.slice().sort((a, b) => b.opcoes.length - a.opcoes.length)[0];
  if (q) q.opcoes[q.opcoes.length - 1].perfil = p.k;
}
const prova_pos = V.dados.prova ? Math.min(Math.max(2, parseInt(e.prova_depois_da_pergunta, 10) || Math.ceil(perguntas.length / 2)), Math.max(2, perguntas.length - 1)) : 0;
const valido = ok && perguntas.length >= Math.min(4, V.op.perguntas);
const est = { promessa: T(e.promessa, 200), titulo_quiz: T(e.titulo_quiz, 90), perfis, perguntas, prova_pos };
const texto_copy = `${V.resumo_ia}

ESTRATÉGIA APROVADA:
PROMESSA DO QUIZ: ${est.promessa || '(defina)'}
PERFIS DE RESULTADO:
${perfis.map(p => `${p.k}. ${p.emoji} ${p.nome} — quem é: ${p.quem_e} — o que recomendar: ${p.recomendacao}`).join('\n')}
PERGUNTAS:
${perguntas.map(q => `${q.k}. ${q.texto} [${q.opcoes.map(o => o.emoji + ' ' + o.texto + ' → ' + o.perfil).join(' | ')}]`).join('\n')}
PROVA SOCIAL: ${prova_pos ? 'aparece depois da pergunta ' + prova_pos + ' (use SÓ a prova social do dono)' : 'não tem (o dono não deu)'}`;
return [{ json: { valido, est, texto_copy, erro: valido ? '' : 'A IA estrategista não montou as perguntas agora. Tente de novo.' } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Regras do funil de quiz (iguais na copywriter, na revisora e na montagem).
// corta no fim de uma frase (ou de uma palavra, com "…"): nunca no meio da palavra
const qzT = (v, max) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max), fim = Math.max(c.lastIndexOf('. '), c.lastIndexOf('! '), c.lastIndexOf('? '));
  if (fim >= max * 0.55) return c.slice(0, fim + 1);
  const esp = c.lastIndexOf(' ');
  return (esp >= max * 0.55 ? c.slice(0, esp) : c.slice(0, max - 1)).replace(/[\s,;:.–—-]+$/, '') + '…';
};
const qzHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const qzLum = h => qzHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const qzContraste = (a, b) => { const x = qzLum(a), y = qzLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const qzMistura = (a, b, k) => { const x = qzHex(a), y = qzHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
// cor da marca: botão com texto legível (4,5:1) e cor de link/destaque que aparece no branco (4,5:1)
function qzTokens(cor) {
  let c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : '#4F46E5';
  let forte = c;
  for (let i = 0; i < 14 && qzContraste(forte, '#FFFFFF') < 4.5; i++) forte = qzMistura(forte, '#000000', 0.12);
  return { cor: c, forte, corTinta: qzContraste('#FFFFFF', c) >= 4.5 ? '#FFFFFF' : '#111111', fundo: qzMistura(c, '#FFFFFF', 0.93), suave: qzMistura(c, '#FFFFFF', 0.86), linha: qzMistura(c, '#FFFFFF', 0.7) };
}
// textos da copywriter (ou da revisora) no formato que a página usa, com tamanho máximo e o que faltar preenchido
function qzCopia(c, est) {
  c = c || {};
  const cp = c.capa || {}, an = c.analisando || {}, ca = c.captura || {}, of = c.oferta || {}, pv = c.prova || {};
  const perfisIn = Array.isArray(c.perfis) ? Object.fromEntries(c.perfis.map((x, i) => [(x && x.k) || est.perfis[i] && est.perfis[i].k, x])) : (c.perfis || {});
  const out = {
    capa: { titulo: qzT(cp.titulo, 90) || est.titulo_quiz || 'Descubra o ideal para você', subtitulo: qzT(cp.subtitulo, 170), botao: qzT(cp.botao, 30) || 'Começar o quiz', selo: qzT(cp.selo, 40) || `⏱️ ${est.perguntas.length} perguntas rápidas` },
    ajudas: {},
    prova: est.prova_pos ? { titulo: qzT(pv.titulo, 80) || 'Quem já passou por aqui', itens: (Array.isArray(pv.itens) ? pv.itens : []).map(i => ({ texto: qzT(i && (i.texto || i), 240), autor: qzT(i && i.autor, 60) })).filter(i => i.texto).slice(0, 3) } : null,
    analisando: { titulo: qzT(an.titulo, 70) || 'Analisando suas respostas…', passos: (Array.isArray(an.passos) ? an.passos : []).map(p => qzT(p, 60)).filter(Boolean).slice(0, 3) },
    captura: { titulo: qzT(ca.titulo, 80) || 'Seu resultado está pronto!', texto: qzT(ca.texto, 220) || 'Diga para onde mandamos o seu resultado.', botao: qzT(ca.botao, 30) || 'Ver meu resultado' },
    perfis: {},
    oferta: { titulo: qzT(of.titulo, 90), texto: qzT(of.texto, 400), botao: qzT(of.botao, 40) || 'Quero conhecer' },
    mensagem_whatsapp: qzT(c.mensagem_whatsapp, 300),
    imagens: {},
  };
  if (out.analisando.passos.length < 3) out.analisando.passos = ['Lendo suas respostas', 'Comparando com os perfis', 'Montando sua recomendação'];
  if (out.prova && !out.prova.itens.length) out.prova = null;
  est.perguntas.forEach(q => { const a = qzT((c.ajudas || {})[q.k], 120); if (a) out.ajudas[q.k] = a; });
  est.perfis.forEach(p => {
    const x = perfisIn[p.k] || perfisIn[p.orig] || {};
    out.perfis[p.k] = { titulo: qzT(x.titulo, 90) || `Seu perfil: ${p.nome}`, descricao: qzT(x.descricao, 450) || p.quem_e, motivos: (Array.isArray(x.motivos) ? x.motivos : []).map(m => qzT(m, 150)).filter(Boolean).slice(0, 3),
      recomendacao: qzT(x.recomendacao, 420) || p.recomendacao, botao: qzT(x.botao, 40) };
  });
  const im = c.imagens || {};
  out.imagens.capa = qzT(im.capa, 600);
  est.perfis.forEach(p => { out.imagens[p.k] = qzT(im[p.k] || im[p.orig], 600); });
  return out;
}
// trava: preço, porcentagem, garantia e escassez só se o dono escreveu. A frase que inventou sai do texto.
function qzGuarda(copia, d) {
  const fonte = [d.preco, d.condicao, d.garantia, d.descricao, d.prova, d.produto].join(' \n ');
  const numsFonte = (fonte.match(/\d+(?:[.,]\d+)*/g) || []).map(n => n.replace(/[.,]/g, ''));
  const problemas = [];
  const proibido = frase => {
    const din = [...frase.matchAll(/R\$\s?(\d+(?:[.,]\d+)*)/g)].map(m => m[1].replace(/[.,]/g, ''));
    const pct = [...frase.matchAll(/(\d+(?:[.,]\d+)?)\s?%/g)].map(m => m[1].replace(/[.,]/g, ''));
    if (din.some(n => !numsFonte.includes(n)) || pct.some(n => !numsFonte.includes(n))) return 'valor ou desconto que você não informou';
    if (!d.garantia && /garanti[ad]|reembolso|devolu[cç][aã]o do dinheiro/i.test(frase)) return 'garantia que você não informou';
    if (!/hoje|vaga|limitad|[uú]ltim/i.test(d.condicao) && /(s[oó] hoje|[uú]ltimas vagas|por tempo limitado|vagas limitadas|acaba hoje|[uú]ltimas unidades)/i.test(frase)) return 'urgência que você não informou';
    return '';
  };
  const limpa = (txt, onde) => {
    if (typeof txt !== 'string' || !txt) return txt;
    const frases = txt.match(/[^.!?]+[.!?]*\s*/g) || [txt];
    const ficam = frases.filter(f => { const m = proibido(f); if (m) problemas.push(`${onde}: tirei "${f.trim().slice(0, 80)}" (${m})`); return !m; });
    return ficam.join('').trim();
  };
  const varre = (o, onde) => {
    for (const k of Object.keys(o)) {
      if (k === 'imagens') continue;
      if (typeof o[k] === 'string') o[k] = limpa(o[k], onde + k);
      else if (Array.isArray(o[k])) o[k] = o[k].map((x, i) => typeof x === 'string' ? limpa(x, `${onde}${k}[${i + 1}]`) : (x && typeof x === 'object' ? (varre(x, `${onde}${k}[${i + 1}].`), x) : x)).filter(x => x !== '');
      else if (o[k] && typeof o[k] === 'object') varre(o[k], onde + k + '.');
    }
  };
  varre(copia, '');
  return problemas;
}
const qzEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// números do funil (o painel e a IA analista usam a mesma conta): visitas por etapa, quem saiu, respostas e leads
function qzMetricas(quiz, vis, resp, leadsMapa) {
  const v = k => Number((vis || {})[`qzv:${quiz.id}:${k}`]) || 0;
  const todos = Object.values(leadsMapa || {}).map(x => { try { return JSON.parse(x); } catch (e) { return null; } }).filter(Boolean).sort((a, b) => b.quando - a.quando);
  const vistos = new Set(), leads = todos.filter(l => { if (vistos.has(l.sessao)) return false; vistos.add(l.sessao); return true; });   // 1 lead por sessão
  const funil = [{ k: 'capa', nome: 'Abriram o quiz', n: v('capa') }]
    .concat(quiz.perguntas.map((p, i) => ({ k: p.k, nome: `Pergunta ${i + 1}`, texto: p.texto, n: v(p.k) })))
    .concat([{ k: 'captura', nome: 'Chegaram na captura', n: v('captura') }, { k: 'lead', nome: 'Deixaram o contato', n: leads.length }, { k: 'oferta', nome: 'Clicaram na oferta', n: v('oferta') }]);
  const ini = funil[0].n;
  funil.forEach((e, i) => {
    e.pct = ini ? Math.round(e.n / ini * 1000) / 10 : 0;
    e.saiu = i ? Math.max(0, funil[i - 1].n - e.n) : 0;
    e.saiu_pct = i && funil[i - 1].n ? Math.round(e.saiu / funil[i - 1].n * 1000) / 10 : 0;
  });
  const perguntas = quiz.perguntas.map((p, i) => {
    const n = o => Number((resp || {})[`qzr:${quiz.id}:${p.k}:${o.k}`]) || 0, tot = p.opcoes.reduce((a, o) => a + n(o), 0);
    return { k: p.k, n: i + 1, texto: p.texto, total: tot, opcoes: p.opcoes.map(o => ({ k: o.k, texto: o.texto, emoji: o.emoji, perfil: o.perfil, n: n(o), pct: tot ? Math.round(n(o) / tot * 1000) / 10 : 0 })) };
  });
  const perfis = quiz.perfis.map(p => ({ k: p.k, nome: p.nome, emoji: p.emoji, n: leads.filter(l => l.perfil === p.k).length }));
  const quedas = funil.slice(1, -1).filter(e => e.saiu > 0).sort((a, b) => b.saiu - a.saiu);
  return { funil, perguntas, perfis, leads, maior_queda: quedas[0] || null,
    total: { abriram: ini, comecaram: v(quiz.perguntas[0].k), captura: v('captura'), leads: leads.length, oferta: v('oferta'), quentes: leads.filter(l => l.temperatura === 'quente').length,
      conversao: ini ? Math.round(leads.length / ini * 1000) / 10 : 0 } };
}

// Confere os textos da copywriter (formato, tamanhos, o que faltar) e prepara o pedido da revisora.
const V = $('🧩 Confere o pedido').first().json, E = $('🧩 Lê a estratégia').first().json;
let c = null;
try { c = parseJSON($('🤖 Copywriter do funil').first().json.output); } catch (e) {}
const copia = qzCopia(c, E.est);
return [{ json: { veio: !!c, copia, texto_revisora: `DADOS DO DONO (a única fonte de verdade):
${V.resumo_ia}

ESTRATÉGIA (perfis e perguntas):
${E.est.perfis.map(p => `${p.k}. ${p.nome}: ${p.quem_e}`).join('\n')}

TEXTOS DA COPYWRITER (JSON):
${JSON.stringify(copia)}` } }];

