// Monta o quiz: estratégia + textos revisados + imagens + cores (contraste garantido) + destino do botão final.
const tenta = f => { try { return f(); } catch (e) { return null; } };
const V = $('🧩 Confere o pedido').first().json, E = $('🧩 Lê a estratégia').first().json, R = $('🧩 Aplica a revisão').first().json;
const guardadas = tenta(() => $('🛠️ Oficina: guarda as imagens').first().json.imagens) || [];
