  id: V.id, chave: V.chave, versao: 1, criado_em: V.criado_em, marca: d.marca, produto: d.produto, preco: d.preco, condicao: d.condicao, garantia: d.garantia,
  destino: V.op.destino, whatsapp: V.op.whatsapp, checkout: V.op.checkout, crm: V.op.crm, cores: qzTokens(V.op.cor || '#4F46E5'), tipo: d.tipo,
