  });
  const perfis = quiz.perfis.map(p => ({ k: p.k, nome: p.nome, emoji: p.emoji, n: leads.filter(l => l.perfil === p.k).length }));
  const quedas = funil.slice(1, -1).filter(e => e.saiu > 0).sort((a, b) => b.saiu - a.saiu);
  return { funil, perguntas, perfis, leads, maior_queda: quedas[0] || null,
